 private Object functionFormatNumber(EvalContext context) {
     int argc = getArgumentCount();
     if (argc != 2 && argc != 3) {
         assertArgCount(2);
     }

     double num =
         InfoSetUtil.doubleValue(getArg1().computeValue(context));
     String fmtPattern =
         InfoSetUtil.stringValue(getArg2().computeValue(context));

     DecimalFormatSymbols dfs = null;
     if (argc == 3) {
         String nameOfSymbols =
             InfoSetUtil.stringValue(getArg3().computeValue(context));
         dfs =
             context.getJXPathContext().getDecimalFormatSymbols(nameOfSymbols);
     }
     else {
         NodePointer ptr = context.getCurrentNodePointer();
         Locale loc;
         if (ptr == null) {
             loc = context.getJXPathContext().getLocale();
         }
         else {
             loc = ptr.getLocale();
         }
         dfs = new DecimalFormatSymbols(loc);
     }

     DecimalFormat decimalFormat = (DecimalFormat) NumberFormat.getInstance();
     decimalFormat.setDecimalFormatSymbols(dfs);
     decimalFormat.applyLocalizedPattern(fmtPattern);
     return decimalFormat.format(num);
 }

